<script setup>
import {computed,ref} from 'vue';import {Head,Link,router} from '@inertiajs/vue3';import {ClipboardList,Clock3,CheckCircle2,TriangleAlert,ArrowUpRight,Download,MapPin,CalendarDays} from 'lucide-vue-next';import Badge from '../Components/Badge.vue';import {date,statuses} from '../lib/labels';
const props=defineProps({stats:Object,recent:Array,maintenances:Array,recurrent:Array,communes:Array,localities:Array,filters:Object});const f=ref({...props.filters});const cards=computed(()=>[{label:'Signalements ouverts',value:props.stats.open,icon:ClipboardList,tone:'orange',note:'À vérifier ou à résoudre'},{label:'Points d’eau hors service',value:props.stats.out_of_service,icon:TriangleAlert,tone:'red',note:'État actuel déclaré'},{label:'Délai de prise en charge',value:props.stats.response_hours===null?'—':props.stats.response_hours+' h',icon:Clock3,tone:'blue',note:props.stats.response_count+' incidents pris en charge'},{label:'Retours de l’eau confirmés',value:props.stats.confirmed,icon:CheckCircle2,tone:'green',note:'Confirmation enregistrée'}]);const exportURL=computed(()=>'/tableau-de-bord?'+new URLSearchParams({...Object.fromEntries(Object.entries(f.value).filter(([k,v])=>v)),export:1}));function filter(){router.get('/tableau-de-bord',f.value,{preserveState:true});}
</script><template><Head title="Tableau de bord"/><div class="page-heading heading-row"><div><span class="eyebrow">CHAQUE INTERVENTION FAIT LA DIFFÉRENCE</span><h1>Vue d’ensemble</h1><p>Une vision claire pour agir là où l’eau manque.</p></div><a :href="exportURL" class="btn btn-outline small"><Download :size="17"/> Exporter les données</a></div><form class="filters" @submit.prevent="filter"><select aria-label="Commune" v-model="f.commune_id"><option :value="undefined">Toutes les communes autorisées</option><option v-for="c in communes" :value="c.id" :key="c.id">{{c.name}}</option></select><select aria-label="Localité" v-model="f.locality_id"><option :value="undefined">Toutes les localités</option><option v-for="l in localities" :value="l.id" :key="l.id">{{l.name}}</option></select><input type="date" aria-label="Du" v-model="f.from"><input type="date" aria-label="Au" v-model="f.to"><button class="btn btn-soft small">Filtrer</button></form>
<div class="grid stats-grid"><article class="card stat-card" v-for="c in cards" :key="c.label"><div class="stat-top"><span>{{c.label}}</span><span :class="['mini-icon',c.tone]"><component :is="c.icon" :size="20"/></span></div><strong class="stat-value">{{c.value}}</strong><small>{{c.note}}</small></article></div>
<div class="dashboard-banner"><div><span class="eyebrow">LA PRIORITÉ : LE RETOUR DE L’EAU</span><h2>Des signalements aux solutions,<br>gardons le lien.</h2><p>{{stats.blocked}} incident(s) avec un blocage déclaré.</p></div><Link href="/incidents" class="btn btn-white">Coordonner les interventions <ArrowUpRight :size="18"/></Link></div>
<div class="grid dashboard-columns"><section class="card table-card"><div class="card-heading"><h3>Derniers signalements</h3><Link href="/incidents" class="text-link">Tout voir ↗</Link></div><div class="table-wrap"><table><thead><tr><th>Point d’eau</th><th>Statut</th><th>Signalé le</th><th></th></tr></thead><tbody><tr v-for="i in recent" :key="i.id"><td><strong>{{i.water_point?.name||'Point non répertorié'}}</strong><small>{{i.locality?.name}} · {{i.reference}}</small></td><td><Badge :value="i.status"/></td><td>{{date(i.created_at)}}</td><td><Link :href="'/incidents/'+i.id" class="icon-button" aria-label="Ouvrir le signalement"><ArrowUpRight :size="18"/></Link></td></tr><tr v-if="!recent.length"><td colspan="4" class="empty">Aucun signalement dans ce périmètre.</td></tr></tbody></table></div></section><section class="card"><div class="card-heading"><h3>État des signalements</h3><ClipboardList :size="19"/></div><div class="status-bar-row" v-for="(count,status) in stats.by_status" :key="status"><div><span>{{statuses[status]}}</span><strong>{{count}}</strong></div><progress :value="count" :max="Math.max(1,...Object.values(stats.by_status))"></progress></div><p v-if="!Object.keys(stats.by_status).length" class="empty">Aucune donnée à afficher.</p><div class="metric-note"><strong>{{stats.resolution_hours===null?'—':stats.resolution_hours+' h'}}</strong><p>Délai moyen de remise en service confirmée<br><small>{{stats.resolution_count}} incident(s) confirmé(s)</small></p></div></section></div>
<div class="grid two mt"><section class="card"><div class="card-heading"><h3>Entretiens à suivre</h3><Link href="/entretiens" class="text-link">Consulter ↗</Link></div><div v-for="m in maintenances" :key="m.id" class="list-row"><span class="mini-icon blue"><CalendarDays :size="18"/></span><div><strong>{{m.water_point?.name}}</strong><small>{{date(m.scheduled_at)}} · {{m.responsible?.name}}</small></div><span v-if="m.scheduled_at<new Date().toLocaleDateString('en-CA')" class="badge hors_service">En retard</span></div><p v-if="!maintenances.length" class="empty">Aucun entretien à suivre.</p></section><section class="card"><h3>Pannes récurrentes</h3><div v-for="p in recurrent" :key="p.name" class="list-row"><MapPin :size="18"/><strong>{{p.name}}</strong><span class="count-chip">{{p.count}} incidents</span></div><p v-if="!recurrent.length" class="empty">Aucune récurrence dans la période sélectionnée.</p><p class="muted mt">Les délais sont calculés depuis le signalement, sur les seuls incidents ayant la date correspondante. Les doublons sont exclus des récurrences.</p></section></div></template>
